def build_trie(words):
    trie = {}
    for word in words:
        word = word.strip().upper()
        if 2 <= len(word) <= 16 and word.isascii() and word.isalpha():
            node = trie
            for letter in word:
                node = node.setdefault(letter, {})
            node["!"] = word
    return trie

# Values counted from the user's supplied game screenshots.
# C=2 is user-confirmed. J=4, Q=4, Z=4 are guesses and remain editable.
LETTER_POINTS = dict(A=2, B=3, C=2, D=2, E=1, F=3, G=3, H=3, I=2,
                     J=4, K=4, L=1, M=2, N=1, O=2, P=3, Q=4, R=1,
                     S=1, T=1, U=2, V=4, W=3, X=4, Y=3, Z=4)

def estimated_rank(word, points):
    return len(word) * sum(points.get(letter, 0) for letter in word)


NEIGHBORS = [
    tuple(j for j in range(16) if j != i and
          abs(i // 4 - j // 4) <= 1 and abs(i % 4 - j % 4) <= 1)
    for i in range(16)
]

def solve(board, trie, points=None, blocked=(), preferred=(), only=None):
    """Return [(word, path)] best first. Same results as before, found faster:
    zero-dot letters are pruned immediately instead of filtering at the end,
    and scores are summed incrementally during the search."""
    board = list(board)
    if points is not None:
        # Letters with 0 dots are "unknown" and exclude any word using them.
        board = [c if points.get(c, 0) > 0 else None for c in board]
        value = [points.get(c, 0) if c else 0 for c in board]
    else:
        value = [0] * 16
    found = {}
    path = []
    neighbors = NEIGHBORS

    def visit(i, node, used, total):
        child = node.get(board[i])
        if child is None:
            return
        path.append(i)
        total += value[i]
        word = child.get("!")
        if word is not None and word not in found and word not in blocked and (only is None or word in only):
            found[word] = (tuple(path), total)
        used |= 1 << i
        for j in neighbors[i]:
            if not used >> j & 1 and board[j] is not None:
                visit(j, child, used, total)
        path.pop()

    for i in range(16):
        if board[i] is not None:
            visit(i, trie, 0, 0)

    if points is None:
        ordered = sorted(found, key=lambda w: (w not in preferred, -len(w), w))
    else:
        ordered = sorted(found, key=lambda w: (w not in preferred, -len(w) * found[w][1], -len(w), w))
    return [(w, found[w][0]) for w in ordered]

REJECTED_FILE = Path.home() / "Library" / "Application Support" / "TriumphWordLink" / "rejected_words.txt"

def load_rejected():
    """Words the game refused. Saved between runs so they are never suggested again."""
    try:
        return {w.strip().upper() for w in REJECTED_FILE.read_text().splitlines() if w.strip()}
    except OSError:
        return set()

ACCEPTED_FILE = REJECTED_FILE.with_name("accepted_words.txt")

def load_accepted():
    """Words the game has taken. Shown first, and can be the only words suggested."""
    try:
        return {w.strip().upper() for w in ACCEPTED_FILE.read_text().splitlines() if w.strip()}
    except OSError:
        return set()

def save_accepted(words):
    try:
        ACCEPTED_FILE.parent.mkdir(parents=True, exist_ok=True)
        ACCEPTED_FILE.write_text("\n".join(sorted(words)) + "\n")
    except OSError:
        pass

def save_rejected(words):
    try:
        REJECTED_FILE.parent.mkdir(parents=True, exist_ok=True)
        REJECTED_FILE.write_text("\n".join(sorted(words)) + "\n")
    except OSError:
        pass


class BoardGate:
    """Confirm a board before solving.
    A reading is trusted when the screen has stopped changing (same frame twice)
    and all 16 tiles were read, or when the last few distinct frames agree on
    every tile by majority vote. Tiles that flicker between a letter and "?"
    no longer force a full re-read, and a mid-animation frame cannot slip through."""
    LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    def __init__(self, window=3):
        self.window = window
        self.history = []

    def accept(self, board, stable=False):
        board = tuple(board)
        if len(board) != 16 or any(len(c) != 1 for c in board):
            return None
        if not stable:
            self.history = (self.history + [board])[-self.window:]
        complete = all(c in self.LETTERS for c in board)
        if stable and complete:
            return list(board)
        merged = []
        for tile in range(16):
            votes = {}
            for reading in self.history:
                letter = reading[tile]
                if letter in self.LETTERS:
                    votes[letter] = votes.get(letter, 0) + 1
            if not votes:
                return None
            letter, count = max(votes.items(), key=lambda item: item[1])
            if count < 2 or board[tile] in self.LETTERS and board[tile] != letter:
                return None
            merged.append(letter)
        return merged


class App:
    def __init__(self, root):
        self.root = root
        self.events = queue.Queue()
        self.stop = threading.Event()
        self.region = None
        self.running = False
        self.trie = None
        self.trie_lock = threading.Lock()
        self.points = dict(LETTER_POINTS)
        self.blocked = load_rejected()
        self.accepted = load_accepted()
        self.known_only = False   # plain bool: the OCR thread reads it, Tk variables are main-thread only
        self.current_index = 0
        self.current_word = ""
        self.temp = tempfile.TemporaryDirectory(prefix="wordlink-")
        self.folder = Path(self.temp.name)
        root.title("Triumph Word Link Solver")
        root.geometry("660x720")
        tk.Label(root, text="Word Link • Scrabble TWL06", font=("Helvetica", 20)).pack(pady=10)
        tk.Label(root, text="Keep the mirrored board visible. Select its exact outside edges.\n"
                 "Paths use row,column. Diagonals allowed; no tile reuse.").pack()
        self.status = tk.StringVar(value="Ready. Select the board, then start live scanning.")
        tk.Label(root, textvariable=self.status, wraplength=620).pack(pady=8)
        bar = tk.Frame(root)
        bar.pack()
        tk.Button(bar, text="1. Select board", command=self.select).pack(side="left", padx=5)
        tk.Button(bar, text="2. Start live", command=self.start).pack(side="left", padx=5)
        tk.Button(bar, text="Pause", command=self.pause).pack(side="left", padx=5)
        tk.Button(root, text="Show captured board", command=self.show_capture).pack(pady=4)
        tk.Button(root, text="Edit letter point values", command=self.edit_points).pack(pady=2)
        tk.Label(root, text="Correct letters here if needed (16 letters, row by row):").pack(pady=(12, 2))
        self.entry = tk.Entry(root, font=("Courier", 18), width=25)
        self.entry.pack()
        tk.Button(root, text="Solve entered letters (pauses live)", command=self.manual).pack(pady=5)
        self.visual_title = tk.StringVar(value="Best estimated option appears automatically")
        tk.Label(root, textvariable=self.visual_title, font=("Helvetica", 13), wraplength=620).pack(pady=4)
        self.visual = tk.Canvas(root, width=240, height=220, bg="#172336", highlightthickness=0)
        self.visual.pack()
        choices = tk.Frame(root)
        choices.pack(pady=4)
        tk.Button(choices, text="◀ Previous", command=lambda: self.show_answer(self.current_index - 1)).pack(side="left", padx=4)
        tk.Button(choices, text="Next best ▶", command=lambda: self.show_answer(self.current_index + 1)).pack(side="left", padx=4)
        tk.Button(choices, text="✓ Game accepted it", command=self.accept_word).pack(side="left", padx=4)
        tk.Button(choices, text="✗ Game rejected it", command=self.reject_word).pack(side="left", padx=4)
        self.known_var = tk.BooleanVar(value=False)
        tk.Checkbutton(root, text="Only suggest words the game has accepted", variable=self.known_var,
                       command=self.toggle_known_only).pack()
        tk.Button(root, text="Clear rejected words", command=self.clear_rejected).pack(pady=2)
        root.bind("<Right>", lambda event: self.show_answer(self.current_index + 1))
        root.bind("<Left>", lambda event: self.show_answer(self.current_index - 1))
        self.visual_board = []
        self.visual_answers = []
        self.output = tk.Text(root, font=("Courier", 13), wrap="none", height=12)
        root.protocol("WM_DELETE_WINDOW", self.close)
        root.after(100, self.poll)
        # Build the word trie while the user is still selecting the board.
        threading.Thread(target=self.dictionary, daemon=True).start()

    def select(self):
        if self.running:
            self.status.set("Pause and wait for scanning to stop before selecting again.")
            return
        overlay = tk.Toplevel(self.root)
        overlay.overrideredirect(True)
        overlay.geometry(f"{self.root.winfo_screenwidth()}x{self.root.winfo_screenheight()}+0+0")
        overlay.attributes("-topmost", True)
        overlay.attributes("-alpha", 0.2)
        canvas = tk.Canvas(overlay, bg="black", cursor="crosshair")
        canvas.pack(fill="both", expand=True)
        canvas.create_text(30, 35, anchor="nw", fill="white", font=("Helvetica", 24),
                           text="Drag around the 4×4 letter grid. Escape cancels.")
        overlay.focus_force()
        origin = []
        rectangle = []
        def down(event):
            origin[:] = [event.x_root, event.y_root]
            canvas.delete("selection")
            rectangle[:] = [canvas.create_rectangle(event.x, event.y, event.x, event.y,
                            outline="cyan", width=6, tags="selection")]
        def motion(event):
            if origin and rectangle:
                canvas.coords(rectangle[0], origin[0]-canvas.winfo_rootx(),
                              origin[1]-canvas.winfo_rooty(), event.x, event.y)
        def up(event):
            if not origin:
                return
            x, y = origin
            left, top = min(x, event.x_root), min(y, event.y_root)
            width, height = abs(event.x_root-x), abs(event.y_root-y)
            if width > 40 and height > 40:
                self.region = (left, top, width, height)
                self.status.set("Board selected. Keep the mirroring window in this position.")
            overlay.destroy()
        canvas.bind("<ButtonPress-1>", down)
        canvas.bind("<B1-Motion>", motion)
        canvas.bind("<ButtonRelease-1>", up)
        overlay.bind("<Escape>", lambda event: overlay.destroy())

    def dictionary(self):
        with self.trie_lock:
            if self.trie is None:
                local = Path(__file__).with_name("words.txt")
                if local.exists():
                    words = local.read_text(errors="ignore").splitlines()
                else:
                    words = zlib.decompress(base64.b64decode(SCRABBLE_WORDS)).decode("ascii").splitlines()
                self.trie = build_trie(words)
            return self.trie

    def start(self):
        if self.running:
            return
        if not self.region:
            messagebox.showinfo("Select board", "Click Select board and drag around the letters first.")
            return
        self.stop.clear()
        self.running = True
        self.status.set("Preparing native OCR. The first run may take a little while.")
        threading.Thread(target=self.worker, daemon=True).start()

    def worker(self):
        process = None
        selector = None
        error_log = None
        try:
            trie = self.dictionary()
            cache_dir = Path.home() / "Library" / "Caches" / "TriumphWordLink"
            binary = None
            versions = (("", OBJC), ("older ", OBJC_PREV), ("original ", OBJC_LEGACY))
            for index, (label, code) in enumerate(versions):
                last_choice = index == len(versions) - 1
                candidate = cache_dir / ("ocr-" + hashlib.sha256(code.encode()).hexdigest()[:12])
                failed_marker = candidate.with_name(candidate.name + ".failed")
                if candidate.exists():
                    binary = candidate
                    break
                if failed_marker.exists() and not last_choice:
                    continue    # this helper already failed to compile on this Mac
                self.events.put(("status", f"Compiling the {label}OCR helper once (cached for next time)..."))
                check = subprocess.run(["/usr/bin/xcode-select", "-p"], capture_output=True)
                if check.returncode:
                    raise RuntimeError("Apple Command Line Tools needed. Open Terminal, run xcode-select --install, then retry.")
                source = self.folder / "ocr.m"
                built = self.folder / "ocr"
                built.unlink(missing_ok=True)
                source.write_text(code)
                result = subprocess.run(["/usr/bin/xcrun", "clang", "-O2", "-fobjc-arc", str(source),
                    "-framework", "Foundation", "-framework", "Vision", "-framework", "ImageIO",
                    "-framework", "CoreGraphics", "-o", str(built)],
                                        capture_output=True, text=True, timeout=180)
                if result.returncode:
                    errors = result.stdout + result.stderr
                    if last_choice:
                        self.events.put(("details", errors))
                        raise RuntimeError("OCR build failed. Full error is shown below; send its first error lines.")
                    try:
                        cache_dir.mkdir(parents=True, exist_ok=True)
                        failed_marker.write_text(errors)
                    except OSError:
                        pass
                    self.events.put(("details", "The newest OCR helper did not compile, so an older one is being used.\n"
                                                "Send the first error lines below to get this fixed:\n\n" + errors[:3000]))
                    continue
                binary = built
                try:
                    cache_dir.mkdir(parents=True, exist_ok=True)
                    staged = candidate.with_name(candidate.name + ".tmp")
                    shutil.copy2(built, staged)
                    os.replace(staged, candidate)
                    binary = candidate
                except OSError:
                    pass   # cache unavailable; use the temp copy this run
                break
            error_log = (self.folder / "ocr_errors.log").open("w")
            process = subprocess.Popen([str(binary)], stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                       stderr=error_log, text=True, bufsize=1)
            selector = selectors.DefaultSelector()
            selector.register(process.stdout, selectors.EVENT_READ)
            previous_hash = None
            previous_board = None
            last = None
            gate = BoardGate()
            waiting = False
            last_unreadable = None
            while not self.stop.is_set():
                started = time.monotonic()
                image = self.folder / "board.png"
                image.unlink(missing_ok=True)
                (self.folder / "board.png.clean.png").unlink(missing_ok=True)
                result = subprocess.run(["/usr/sbin/screencapture", "-x", "-R" +
                    ",".join(map(str, self.region)), str(image)], capture_output=True, timeout=10)
                if result.returncode or not image.exists():
                    raise RuntimeError("Screen capture failed. Enable Screen Recording for IDLE/Python in System Settings, then restart IDLE.")
                image_hash = hashlib.sha256(image.read_bytes()).digest()
                unchanged = image_hash == previous_hash and previous_board is not None
                if unchanged:
                    board = previous_board
                else:
                    process.stdin.write(str(image) + "\n")
                    process.stdin.flush()
                    if not selector.select(timeout=15):
                        raise RuntimeError("OCR timed out. Pause and restart live scanning.")
                    line = process.stdout.readline()
                    if not line:
                        raise RuntimeError("OCR helper stopped. " + (self.folder / "ocr_errors.log").read_text()[-500:])
                    board = json.loads(line)
                    if isinstance(board, dict):
                        raise RuntimeError(board.get("error", "OCR failed"))
                    previous_hash = image_hash
                    previous_board = board
                confirmed = gate.accept(board, unchanged)
                accepted = confirmed is not None
                if accepted:
                    board = confirmed
                if not accepted:
                    if "?" in board or "!" in board:
                        if board != last_unreadable:
                            self.events.put(("unreadable", ["?" if c == "!" else c for c in board]))
                            last_unreadable = board
                            waiting = True
                    elif not waiting:
                        self.events.put(("waiting", "Reading letters—waiting for two matching complete scans."))
                        waiting = True
                elif board != last or waiting:
                    answers = solve(board, trie, self.points, self.blocked, self.accepted, self.accepted if self.known_only else None)
                    self.events.put(("board", (board, answers, time.monotonic()-started)))
                    last = board
                    last_unreadable = None
                    waiting = False
                # Nothing new on screen: poll gently instead of spinning.
                self.stop.wait(0.15 if unchanged and accepted else 0.03)
        except Exception as error:
            self.events.put(("status", str(error)))
        finally:
            if selector is not None:
                selector.close()
            if process is not None:
                if process.poll() is None:
                    process.terminate()
                    try:
                        process.wait(timeout=2)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.wait()
                if process.stdin:
                    process.stdin.close()
                if process.stdout:
                    process.stdout.close()
            if error_log is not None:
                error_log.close()
            self.events.put(("stopped", None))

    def edit_points(self):
        if self.running:
            self.pause()
            self.status.set("Pausing. Click Edit letter point values again when scanning stops.")
            return
        text = simpledialog.askstring("Letter dots", "Enter values counted from dots. 0 = unknown.\n"
            "Example: A=2 B=3 C=3. These are letter values, not Scrabble scores.",
            initialvalue=" ".join(f"{letter}={value}" for letter,value in sorted(self.points.items())))
        if text is None:
            return
        try:
            updated = {}
            for pair in text.upper().replace(",", " ").split():
                letter, number = pair.split("=")
                if len(letter) != 1 or letter not in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
                    raise ValueError()
                value = int(number)
                if not 0 <= value <= 20:
                    raise ValueError()
                updated[letter] = value
            self.points.update(updated)
            if self.visual_board and "?" not in self.visual_board:
                self.render(self.visual_board, self.solve_board(self.visual_board), 0)
        except ValueError:
            messagebox.showerror("Values", "Use space-separated entries such as A=2 B=3 C=3.")

    def show_capture(self):
        image = self.folder / "board.png"
        if not image.exists():
            messagebox.showinfo("Capture", "Click Start live first to capture the selected board.")
            return
        try:
            for name, preview_name in (("board.png", "capture_preview.png"),
                                       ("board.png.clean.png", "cleaned_preview.png")):
                source = self.folder / name
                if source.exists():
                    preview = self.folder / preview_name
                    preview.write_bytes(source.read_bytes())
                    subprocess.Popen(["/usr/bin/open", str(preview)])
        except OSError as error:
            messagebox.showerror("Capture", str(error))

    def pause(self):
        self.stop.set()

    def manual(self):
        self.pause()
        if self.running:
            self.status.set("Pausing. Click Solve entered letters again once live scanning stops.")
            return
        board = "".join(self.entry.get().upper().split())
        if len(board) != 16 or not board.isascii() or not board.isalpha():
            messagebox.showinfo("Letters", "Enter exactly 16 A–Z letters, left to right, top to bottom.")
            return
        try:
            self.render(list(board), self.solve_board(board), 0)
        except Exception as error:
            self.status.set(str(error))

    def solve_board(self, board):
        return solve(board, self.dictionary(), self.points, self.blocked, self.accepted,
                     self.accepted if self.known_only else None)

    def show_answer(self, index):
        answers = self.visual_answers
        if not answers:
            self.current_index = 0
            self.draw_route()
            return
        index = max(0, min(index, len(answers) - 1))
        self.current_index = index
        self.draw_route(*answers[index])
        known = " • ✓ game accepts" if self.current_word in self.accepted else ""
        self.visual_title.set(self.visual_title.get() + f" • option {index + 1} of {len(answers)}" + known)

    def accept_word(self):
        word = self.current_word
        if not word:
            return
        self.accepted.add(word)
        self.blocked.discard(word)
        save_accepted(self.accepted)
        save_rejected(self.blocked)
        self.show_answer(self.current_index)
        self.status.set(f"Saved: the game accepts {word} ({len(self.accepted)} known-good words).")

    def toggle_known_only(self):
        self.known_only = bool(self.known_var.get())
        board = self.visual_board
        if board and "?" not in board:
            answers = self.solve_board(board)
            self.render(board, answers, 0)
            if self.known_only and not answers:
                self.status.set("No accepted words fit this board yet. Mark words with ✓ as the game takes them.")
            elif self.known_only:
                self.status.set(f"Showing only words the game has accepted ({len(self.accepted)} known).")

    def reject_word(self):
        word = self.current_word
        board = self.visual_board
        if not word or not board or "?" in board:
            return
        self.blocked.add(word)
        self.accepted.discard(word)
        save_rejected(self.blocked)
        save_accepted(self.accepted)
        self.render(board, self.solve_board(board), 0)
        tail = "Showing the next best word." if self.visual_answers else "No other words to show for this board."
        self.status.set(f"Removed {word} for good ({len(self.blocked)} rejected words saved). {tail}")

    def clear_rejected(self):
        if self.blocked and messagebox.askyesno("Rejected words", f"Forget all {len(self.blocked)} rejected words?"):
            self.blocked.clear()
            save_rejected(self.blocked)
            self.status.set("Rejected-word list cleared.")

    def draw_route(self, word="", path=()):
        self.current_word = word
        self.visual.delete("all")
        points = {i: (40 + (i % 4)*53, 30 + (i // 4)*53) for i in range(16)}
        for i, letter in enumerate(self.visual_board):
            x, y = points[i]
            self.visual.create_rectangle(x-22, y-22, x+22, y+22,
                fill="#345447" if i in path else "#29384e", outline="#7edba6" if i in path else "#657084")
            self.visual.create_text(x, y, text=letter, fill="white", font=("Helvetica", 20, "bold"))
        for a, b in zip(path, path[1:]):
            ax, ay = points[a]; bx, by = points[b]
            self.visual.create_line(ax, ay, bx, by, fill="#ffd166", width=4, arrow="last")
        for step, i in enumerate(path, 1):
            x, y = points[i]
            self.visual.create_oval(x+9, y-23, x+25, y-7, fill="#ffd166", outline="")
            self.visual.create_text(x+17, y-15, text=str(step), fill="#172336", font=("Helvetica", 10, "bold"))
        self.visual_title.set(f"{word} • {len(word)} letters • {sum(self.points.get(c,0) for c in word)} letter points\n"
                              f"Estimated rank: {estimated_rank(word,self.points)} • follow 1 → {len(path)}" if word
                              else "Best estimated option appears automatically")

    def render(self, board, answers, elapsed):
        self.output.pack_forget()
        self.visual_board = board
        self.visual_answers = answers[:100]
        self.show_answer(0)
        self.entry.delete(0, "end")
        self.entry.insert(0, "".join(board))
        self.output.delete("1.0", "end")
        for row in range(4):
            self.output.insert("end", "  ".join(board[row*4:row*4+4]) + "\n")
        self.output.insert("end", "\nWORD             LENGTH   PATH (row,column)\n")
        for word, path in answers[:100]:
            route = " → ".join(f"{i//4+1},{i%4+1}" for i in path)
            self.output.insert("end", f"{word:<16} {len(word):>3}     {route}\n")
        unknown = sorted({letter for letter in board if self.points.get(letter,0) == 0})
        note = " Set dot values for: " + ", ".join(unknown) + ". Words using them are excluded." if unknown else ""
        self.status.set(f"{len(answers)} ranked words • {elapsed:.2f}s scan/solve. Rank = length × sum of dots; Triumph formula unverified; J/Q/Z values guessed." + note)

    def poll(self):
        try:
            while True:
                kind, data = self.events.get_nowait()
                if kind == "board":
                    self.render(*data)
                elif kind == "waiting":
                    self.draw_route()
                    self.visual_title.set("Waiting for a stable board")
                    self.status.set(data)
                elif kind == "unreadable":
                    self.visual_board = data
                    self.visual_answers = []
                    self.draw_route()
                    self.visual_title.set("Recognized letters (? = unreadable)")
                    self.entry.delete(0, "end")
                    self.entry.insert(0, "".join(data))
                    self.status.set("Unreadable letters. Click Show captured board to check what the program sees.")
                elif kind == "details":
                    self.output.pack(fill="both", expand=True, padx=10, pady=10)
                    self.output.delete("1.0", "end")
                    self.output.configure(wrap="word")
                    self.output.insert("end", data)
                elif kind == "status":
                    self.status.set(data)
                elif kind == "stopped":
                    self.running = False
        except queue.Empty:
            pass
        self.root.after(100, self.poll)

    def close(self):
        self.stop.set()
        self.root.destroy()

if __name__ == "__main__":
    if sys.platform != "darwin":
        raise SystemExit("Run this program on your Mac.")
    root = tk.Tk()
    app = App(root)
    root.mainloop()
